# Basic if statement
age = 18

if age >= 18:
    print("You are an adult!")
    print("You can vote.")

print("\n--- Age Checker ---")

# if-elif-else structure
user_age = 15

if user_age < 13:
    print("You are a child.")
elif user_age < 20:
    print("You are a teenager.")
elif user_age < 65:
    print("You are an adult.")
else:
    print("You are a senior citizen.")

print("\n--- Grade Calculator ---")

# Nested if statements
score = 85

if score >= 90:
    grade = "A"
    if score >= 95:
        grade += "+"
    else:
        grade += "-"
elif score >= 80:
    grade = "B"
    if score >= 85:
        grade += "+"
    else:
        grade += "-"
elif score >= 70:
    grade = "C"
else:
    grade = "F"

print(f"Score: {score}, Grade: {grade}")

# Multiple conditions with logical operators
print("\n--- Movie Ticket Price ---")
age = 25
is_student = False

if age < 12 or age >= 65:
    ticket_price = 8
elif is_student and age < 25:
    ticket_price = 10
else:
    ticket_price = 15

print(f"Ticket price: ${ticket_price}")

# Using break to exit loops early
print('--- Break Example: Finding First Even Number ---')
numbers = [1, 3, 5, 8, 9, 11, 14]
for num in numbers:
    if num % 2 == 0:
        print(f'Found first even number: {num}')
        break
    print(f'Checking {num} - odd')
else:
    print('No even numbers found')

print('
--- Continue Example: Skipping Odd Numbers ---')
for i in range(1, 11):
    if i % 2 != 0:
        continue
    print(i)

print('
--- Validation simulation with predefined data ---')
inputs = ['abc', '50', 'quit', '75']
for value in inputs:
    if value.lower() == 'quit':
        print('Goodbye!')
        break
    if not value.isdigit():
        print(f'Invalid numeric value: {value}')
        continue
    number = int(value)
    if 1 <= number <= 100:
        print(f'{number} is within the valid range.')
    else:
        print(f'{number} is outside the valid range.')
